import { axiosClient } from "../../shared/api/axiosClient";
import { getAxiosErrorMessage, getAxiosErrorStatus } from "../../shared/api/axiosError";

function unwrap(res) {
  const data = res?.data;
  if (!data?.success) throw new Error(data?.message || "Request failed");
  return data;
}

function toNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : 0;
}

function percentage(value) {
  const number = toNumber(value);
  return Number.isFinite(number) ? Math.max(0, Math.min(100, number)) : 0;
}

function attendanceError(err, fallback) {
  const status = getAxiosErrorStatus(err);
  if (status === 401) return "Please log in as a trainer to view attendance.";
  if (status === 403) return "You do not have access to this attendance report.";
  if (status === 404) return "Attendance report is not available yet.";
  if (status >= 500) return "Attendance service is unavailable. Please try again later.";
  return getAxiosErrorMessage(err, fallback);
}

function normalizeStudent(dto) {
  const raw = dto || {};
  const presentCount = toNumber(raw.presentCount ?? raw.present ?? raw.presentSessions);
  const lateCount = toNumber(raw.lateCount ?? raw.late ?? raw.lateSessions);
  const absentCount = toNumber(raw.absentCount ?? raw.absent ?? raw.absentSessions);
  const attendedCount = toNumber(
    raw.attendedCount ?? raw.attended ?? raw.totalAttended ?? presentCount + lateCount
  );
  const totalSessions = toNumber(raw.totalSessions ?? raw.sessionsCount);

  return {
    studentId: String(raw.studentId || raw.id || raw._id || raw.userId || ""),
    fullName: raw.fullName || raw.name || raw.studentName || "Student",
    email: raw.email || raw.emailAddress || raw.EMAIL_ADDRESS || "",
    presentCount,
    lateCount,
    absentCount,
    attendedCount,
    totalSessions,
    attendancePercentage: percentage(
      raw.attendancePercentage ?? raw.attendancePercent ?? raw.percentage
    ),
    eligibilityStatus: raw.eligibilityStatus || raw.certificateEligibility || "Preview pending",
    raw,
  };
}

function normalizeSession(dto) {
  const raw = dto || {};
  const presentCount = toNumber(raw.presentCount ?? raw.present);
  const lateCount = toNumber(raw.lateCount ?? raw.late);
  const absentCount = toNumber(raw.absentCount ?? raw.absent);

  return {
    sessionId: String(raw.sessionId || raw.id || raw._id || ""),
    date: raw.date || raw.sessionDate || raw.scheduledDate || raw.createdAt || "",
    sessionTitle: raw.sessionTitle || raw.title || raw.classTitle || "Session",
    presentCount,
    lateCount,
    absentCount,
    attendancePercentage: percentage(
      raw.attendancePercentage ?? raw.attendancePercent ?? raw.percentage
    ),
    raw,
  };
}

function normalizeSummary(payload) {
  const source = payload?.data || payload?.summary || payload || {};
  const rawStudents = source.students || source.studentAttendance || source.learners || [];
  const rawSessions = source.sessions || source.sessionAttendance || source.sessionReports || [];

  return {
    courseId: String(source.courseId || source.course?._id || source.course?.id || ""),
    courseTitle:
      source.courseTitle ||
      source.courseName ||
      source.course?.title ||
      source.course?.courseTitle ||
      "Course attendance",
    trainerId: String(source.trainerId || source.trainer?._id || source.trainer?.id || ""),
    sessionId: String(source.sessionId || source.session?._id || source.session?.id || ""),
    sessionTitle:
      source.sessionTitle ||
      source.session?.title ||
      source.session?.classTitle ||
      source.title ||
      "Session attendance",
    totalStudents: toNumber(source.totalStudents ?? source.studentsCount),
    totalSessions: toNumber(source.totalSessions ?? source.sessionsCount),
    completedSessions: toNumber(source.completedSessions ?? source.completedSessionCount),
    presentCount: toNumber(source.presentCount ?? source.present),
    lateCount: toNumber(source.lateCount ?? source.late),
    absentCount: toNumber(source.absentCount ?? source.absent),
    attendancePercentage: percentage(
      source.attendancePercentage ?? source.averageAttendancePercentage ?? source.averageAttendance
    ),
    students: Array.isArray(rawStudents) ? rawStudents.map(normalizeStudent) : [],
    sessions: Array.isArray(rawSessions) ? rawSessions.map(normalizeSession) : [],
    eligibility: source.eligibility || source.certificateEligibility || null,
    raw: source,
  };
}

export async function getTrainerCourseAttendanceSummary(courseId) {
  try {
    const res = await axiosClient.get(
      `/api/trainer/courses/${encodeURIComponent(courseId)}/attendance-summary`
    );
    return normalizeSummary(unwrap(res));
  } catch (err) {
    throw new Error(attendanceError(err, "Unable to load course attendance summary."));
  }
}

export async function getTrainerSessionAttendance(sessionId) {
  try {
    const res = await axiosClient.get(
      `/api/trainer/sessions/${encodeURIComponent(sessionId)}/attendance`
    );
    return normalizeSummary(unwrap(res));
  } catch (err) {
    throw new Error(attendanceError(err, "Unable to load session attendance."));
  }
}

export async function getTrainerCourseStudentAttendance(courseId) {
  try {
    const res = await axiosClient.get(
      `/api/trainer/courses/${encodeURIComponent(courseId)}/student-attendance`
    );
    return normalizeSummary(unwrap(res));
  } catch (err) {
    throw new Error(attendanceError(err, "Unable to load student attendance."));
  }
}

export async function getTrainerCourseAttendanceEligibility(courseId) {
  try {
    const res = await axiosClient.get(
      `/api/trainer/courses/${encodeURIComponent(courseId)}/attendance-eligibility`
    );
    return normalizeSummary(unwrap(res));
  } catch (err) {
    throw new Error(attendanceError(err, "Unable to load certificate eligibility preview."));
  }
}
